// Terminal clipboard (#3157) — copy-on-select + paste for the app's xterm terminals (both the console
// panes, `TerminalView`, and the app-owned screen sessions, `useScreenSession`). The terminals had NO
// clipboard handling: Ctrl+C is SIGINT (can't be copy), and Ctrl+Shift+C — the usual terminal copy chord —
// is claimed by the WebView2 DevTools "inspect" accelerator AND the app's broadcast-toggle. So:
//   • COPY-ON-SELECT — selecting text auto-copies (writeText, already proven in this app). No key needed,
//     which sidesteps the Ctrl+Shift+C conflict entirely.
//   • PASTE — Ctrl+Shift+V / Shift+Insert / right-click read the clipboard and `pty_write` it (these chords
//     don't collide with the DevTools accelerator, so paste works standalone).
// Feature-agnostic (shared/), so both terminal sites wire the identical behavior. Must be called AFTER
// `term.open()` — it needs `term.element` for the mouse listeners.
//
// THIS MODULE OWNS THE TERMINAL'S ONE CUSTOM KEY HANDLER (#one-terminal-one-key-handler).
// `attachCustomKeyEventHandler` is an ASSIGNMENT in xterm, not an add-listener — the terminal keeps a
// single handler and the last call silently replaces whatever the previous caller installed. Two callers
// used to attach one to the same terminal: `TerminalView` for the Shift+Enter override (#4134) at
// construction, and this module for the paste chords, later, from `openIfReady`. This one won, so
// Shift+Enter had been dead in every terminal in the app since the two met — invisible to the tests
// because every terminal mock stubs the setter as a bare `vi.fn()`, and last-wins cannot be observed
// through a spy. So the mapping arrives as `keyOverride` and is composed here instead, leaving exactly
// one attach per terminal. Injected rather than imported because that mapping lives in `app/console/`
// and `shared/` must not import a feature.
import type { Terminal } from "@xterm/xterm";
import { fireInvoke } from "@/shared/lib/core/safeInvoke";
import { log } from "@/shared/lib/core/log";

/** A keyboard event, narrowed to what a key mapping reads. Mirrors `TerminalKeyEvent` in app/console. */
export interface ClipboardKeyEvent {
  type: string;
  key: string;
  shiftKey: boolean;
  ctrlKey: boolean;
  altKey: boolean;
  metaKey: boolean;
}

export interface TerminalClipboardOptions {
  /**
   * Consulted BEFORE the paste chords, on every keydown: return the bytes to send to the PTY instead of
   * xterm's default, or `null` to let the key continue. This is how `terminalKeyOverride` (#4134) reaches
   * the terminal's single custom key handler without a second `attachCustomKeyEventHandler` clobbering it.
   */
  keyOverride?: (e: ClipboardKeyEvent) => string | null;
}

/**
 * Wire copy-on-select + paste onto an open xterm `term`, sending pasted text to the PTY `paneId`.
 * Returns a disposer to call on terminal teardown (removes the DOM listeners; xterm keeps a single custom
 * key handler that goes away when the terminal is disposed).
 */
export function attachTerminalClipboard(
  term: Terminal,
  paneId: string,
  opts: TerminalClipboardOptions = {},
): () => void {
  const el = term.element;
  const disposers: Array<() => void> = [];

  // Whether the async clipboard has proven it cannot serve a READ here. WebKitGTK — which is the webview
  // on Linux, where WebView2 is on Windows — rejects `readText()` outside a paste-button gesture, and the
  // failure arrives as a rejected promise AFTER the key was already claimed. So the first refusal is
  // remembered, and from then on the chords are NOT swallowed: the native path (a real paste event, the
  // context menu's own Paste item) is left free to do what this cannot. Reported as "the listeners are
  // eating my paste", which is exactly what a claimed key with a silent no-op behind it feels like.
  let readBroken = false;
  let warned = false;
  const warnOnce = (what: string, why: unknown) => {
    if (warned) return;
    warned = true;
    log.warn(
      `terminal ${paneId}: the async clipboard cannot ${what} here (${String(why)}). ` +
        "Falling back to the browser's native paste — use Ctrl+V, or the right-click menu.",
    );
  };

  // ── COPY-ON-SELECT ── on mouse-up, copy the current selection (one write per finished selection, vs
  // `onSelectionChange` which fires continuously during a drag). A no-selection mouse-up (a plain click,
  // or a click that clears a selection) writes nothing, so it never clobbers the clipboard with "".
  const onMouseUp = () => {
    const sel = term.getSelection();
    if (!sel) return;
    const w = navigator.clipboard?.writeText?.(sel);
    if (!w) return warnOnce("copy", "writeText is unavailable");
    void w.catch((e) => warnOnce("copy", e));
  };
  el?.addEventListener("mouseup", onMouseUp);
  if (el) disposers.push(() => el.removeEventListener("mouseup", onMouseUp));

  // ── PASTE ── read the clipboard and send it to the PTY (the shell / TUI echoes it back).
  // Returns whether the caller should CLAIM the key: `false` means "this could not paste", and the key is
  // deliberately left to the browser rather than being consumed for nothing.
  const paste = (): boolean => {
    if (readBroken) return false;
    let read: Promise<string> | undefined;
    try {
      read = navigator.clipboard?.readText?.();
    } catch (e) {
      readBroken = true;
      warnOnce("read", e);
      return false;
    }
    if (!read) {
      readBroken = true;
      warnOnce("read", "readText is unavailable");
      return false;
    }
    void read
      .then((text) => { if (text) fireInvoke("pty_write", { paneId, data: text }, console.error); })
      .catch((e) => { readBroken = true; warnOnce("read", e); });
    return true;
  };

  // Right-click pastes (terminal convention); suppress the browser context menu so it doesn't also open.
  // Once the read is known-broken the menu is left ALONE on purpose — its own Paste item is native, so it
  // still works where this does not, and suppressing it would remove the last way to paste with a mouse.
  const onContextMenu = (e: MouseEvent) => {
    if (readBroken) return;
    e.preventDefault();
    if (!paste()) return;
  };
  el?.addEventListener("contextmenu", onContextMenu);
  if (el) disposers.push(() => el.removeEventListener("contextmenu", onContextMenu));

  // The terminal's ONE custom key handler: the injected override first, then the paste chords.
  // Returning FALSE stops xterm from ALSO sending the keys to the PTY, and `preventDefault` stops a native
  // paste event from double-firing. Ctrl+Shift+C copy is deliberately NOT bound here — copy-on-select
  // covers it, and on Windows that chord is eaten by the DevTools accelerator until the separate layer-1
  // fix disables the WebView2 browser accelerator keys.
  term.attachCustomKeyEventHandler((e) => {
    if (e.type !== "keydown") return true;

    const bytes = opts.keyOverride?.(e as ClipboardKeyEvent) ?? null;
    if (bytes !== null) {
      fireInvoke("pty_write", { paneId, data: bytes }, console.error);
      return false;
    }

    const paste_v = e.ctrlKey && e.shiftKey && !e.altKey && !e.metaKey && (e.key === "V" || e.key === "v");
    const paste_ins = e.shiftKey && !e.ctrlKey && !e.altKey && !e.metaKey && e.key === "Insert";
    if (paste_v || paste_ins) {
      // Claim the key ONLY if the paste can actually happen; otherwise fall through so xterm and the
      // browser still get their shot at it.
      if (!paste()) return true;
      e.preventDefault();
      return false;
    }
    return true;
  });

  return () => { for (const d of disposers) d(); };
}

